import { useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { ChevronDown, ChevronUp } from 'lucide-react';
import { CopyButton } from './CopyButton';
import { ExportMenu } from './ExportMenu';
import { PromptDNAVisualizer } from './PromptDNAVisualizer';
import { Card } from '@/components/ui/Card';
import { useLanguage } from '@/components/layout/LanguageProvider';
import type { ComposedPrompt } from '@/types/prompt.types';
import { cn } from '@/lib/utils/cn';

interface Props {
  prompt: ComposedPrompt;
}

export function PromptPreview({ prompt }: Props) {
  const [activeIdx, setActiveIdx] = useState(0);
  const [expanded, setExpanded] = useState(true);
  const { t } = useLanguage();

  const activePrompt = prompt.prompts[activeIdx] || '';
  const isChained = prompt.prompts.length > 1;

  return (
    <div className="space-y-4">
      <PromptDNAVisualizer
        sections={prompt.dnaSections}
        strategy={prompt.meta.strategy}
        strategyConfidence={prompt.meta.strategyConfidence}
      />

      <Card padding="lg">
        <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
          <div>
            <h2 className="text-xl font-bold text-text-primary">{t('preview.ready')}</h2>
            <p className="mt-1 text-xs text-text-muted">
              {t('preview.meta', {
                terms: prompt.meta.selectedTermIds.length,
                chars: prompt.meta.totalChars.toLocaleString(),
                format: prompt.meta.isChained ? t('preview.chained') : t('preview.single'),
              })}
            </p>
          </div>
          <CopyButton text={activePrompt} label={t('preview.copyPrompt')} />
        </div>

        {isChained && (
          <div className="mb-4 flex gap-2 overflow-x-auto">
            {prompt.prompts.map((_, i) => (
              <button
                key={i}
                onClick={() => setActiveIdx(i)}
                className={cn(
                  'whitespace-nowrap rounded-lg border px-3 py-1.5 text-xs font-bold transition-all',
                  i === activeIdx
                    ? 'border-primary bg-primary/10 text-primary'
                    : 'border-border bg-surface text-text-secondary hover:border-primary/50',
                )}
              >
                {t('preview.stage', { n: i + 1 })}
              </button>
            ))}
          </div>
        )}

        <button
          onClick={() => setExpanded((v) => !v)}
          className="mb-3 flex items-center gap-1 text-sm font-bold text-primary hover:underline"
        >
          {expanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
          {expanded ? t('preview.hide') : t('preview.show')} {t('preview.prompt')}
        </button>

        {expanded && (
          <div className="max-h-[600px] overflow-y-auto rounded-lg border border-border bg-bg p-4 text-sm">
            <div className="prose prose-invert max-w-none prose-headings:text-primary prose-strong:text-text-primary prose-code:bg-surface-elevated prose-code:px-1 prose-code:rounded">
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{activePrompt}</ReactMarkdown>
            </div>
          </div>
        )}

        <div className="mt-4 border-t border-border pt-4">
          <p className="mb-2 text-xs font-bold text-text-muted">{t('preview.export')}</p>
          <ExportMenu prompt={prompt} />
        </div>
      </Card>
    </div>
  );
}