import { FileJson, FileText, FileCode } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { downloadTxt, downloadMd, downloadJson } from '@/lib/utils/export';
import { useDedicationStore } from '@/lib/store/dedicationStore';
import type { ComposedPrompt } from '@/types/prompt.types';

interface Props {
  prompt: ComposedPrompt;
  baseName?: string;
}

export function ExportMenu({ prompt, baseName = 'prompt-dna' }: Props) {
  const open = useDedicationStore((s) => s.open);

  return (
    <div className="flex flex-wrap gap-2">
      <Button
        variant="secondary"
        size="sm"
        onClick={() => {
          downloadTxt(prompt, baseName);
          open('export');
        }}
      >
        <FileText size={14} /> .txt
      </Button>
      <Button
        variant="secondary"
        size="sm"
        onClick={() => {
          downloadMd(prompt, baseName);
          open('export');
        }}
      >
        <FileCode size={14} /> .md
      </Button>
      <Button
        variant="secondary"
        size="sm"
        onClick={() => {
          downloadJson(prompt, baseName);
          open('export');
        }}
      >
        <FileJson size={14} /> .json
      </Button>
    </div>
  );
}