import { useState } from 'react';
import { Check, Copy } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { copyToClipboard } from '@/lib/utils/clipboard';
import { useDedicationStore } from '@/lib/store/dedicationStore';
import { useLanguage } from '@/components/layout/LanguageProvider';

interface Props {
  text: string;
  label?: string;
  size?: 'sm' | 'md' | 'lg';
}

export function CopyButton({ text, label, size = 'md' }: Props) {
  const [copied, setCopied] = useState(false);
  const open = useDedicationStore((s) => s.open);
  const { t } = useLanguage();

  const handleCopy = async () => {
    const ok = await copyToClipboard(text);
    if (ok) {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
      open('copy');
    }
  };

  const finalLabel = label || t('common.copy');

  return (
    <Button onClick={handleCopy} size={size} variant={copied ? 'secondary' : 'primary'}>
      {copied ? <Check size={16} /> : <Copy size={16} />}
      {copied ? t('common.copied') : finalLabel}
    </Button>
  );
}