// ============================================================
// StrategyPlanner — picks ONE strategic narrative pattern
// BEFORE term selection. This is the missing link identified
// in the architecture audit: we used to jump from audience → terms.
// ============================================================

import type { WizardAnswers } from '@/types/wizard.types';
import type { UseCaseId } from '@/types/knowledge.types';

export interface Strategy {
  id: string;
  name: { ar: string; en: string };
  description: string;
  narrative_flow: string[];
  best_for_goals: string[];
  best_for_tones: string[];
  best_for_content_types: string[];
  required_term_categories: string[];
  recommended_term_ids: number[];
  avoid_term_ids: number[];
  framework_anchors: string[];
}

export interface StrategyFile {
  version: string;
  description: string;
  strategies: Strategy[];
}

export interface StrategyDecision {
  strategy: Strategy;
  confidence: number; // 0-1
  reasoning: string;
  alternatives: Array<{ strategy: Strategy; score: number }>;
}

// ============================================================
// Main planner
// ============================================================
export function planStrategy(
  file: StrategyFile,
  answers: WizardAnswers,
): StrategyDecision {
  // For non-content-creation modes, pick a default
  if (answers.mode !== 'content-creation') {
    return pickDefaultForMode(file, answers.mode);
  }

  const scored = file.strategies.map((s) => ({
    strategy: s,
    score: scoreStrategy(s, answers),
  }));

  scored.sort((a, b) => b.score - a.score);

  const top = scored[0];
  const runner = scored[1];

  // Confidence: relative gap between top and runner
  const gap = runner ? top.score - runner.score : top.score;
  const confidence = Math.min(1, Math.max(0.2, gap / Math.max(top.score, 1)));

  return {
    strategy: top.strategy,
    confidence,
    reasoning: buildReasoning(top.strategy, answers),
    alternatives: scored.slice(1, 4).map((x) => ({ strategy: x.strategy, score: x.score })),
  };
}

// ============================================================
// Scoring: how well does a strategy fit the user's context?
// ============================================================
function scoreStrategy(strategy: Strategy, answers: WizardAnswers): number {
  let score = 0;

  // 1. Goal match (weight 3)
  if (answers.goal) {
    if (strategy.best_for_goals.includes(answers.goal)) score += 30;
    else if (strategy.best_for_goals.some((g) => g.includes(answers.goal!.split(' ')[0]))) score += 10;
  }

  // 2. Tone match (weight 2.5)
  if (answers.tone) {
    if (strategy.best_for_tones.includes(answers.tone)) score += 25;
    else if (strategy.best_for_tones.some((t) => t.includes(answers.tone!.split(' ')[0]))) score += 8;
  }

  // 3. Content type match (weight 2)
  if (answers.contentType) {
    if (strategy.best_for_content_types.includes(answers.contentType)) score += 20;
  }

  // 4. Pain point alignment (bonus)
  if (answers.painPoint) {
    const painTriggers = ['خايفين من الفشل', 'عندهم معلومات خاطئة', 'شايفين الموضوع صعب'];
    if (painTriggers.some((p) => answers.painPoint?.includes(p))) {
      // Strategy that addresses objections works better
      if (['problem-solution', 'myth-busting', 'contrarian-truth'].includes(strategy.id)) {
        score += 15;
      }
    }
  }

  // 5. Platform hints (weight 1.5)
  const platform = (answers.platform || '').toLowerCase();
  if (platform.includes('tiktok') || platform.includes('reel') || platform.includes('short')) {
    // Short-form favors punchy, high-retention strategies
    if (['contrarian-truth', 'listicle-countdown', 'before-after-bridge'].includes(strategy.id)) {
      score += 12;
    }
    if (strategy.id === 'tutorial-breakdown') score -= 8; // tutorials need time
  }

  // 6. Audience familiarity
  if (answers.audience === 'مبتدئين تماماً في المجال') {
    if (strategy.id === 'tutorial-breakdown' || strategy.id === 'myth-busting') score += 10;
    if (strategy.id === 'contrarian-truth') score -= 5; // too provocative for beginners
  }

  return score;
}

// ============================================================
// Default strategies for non content-creation modes
// ============================================================
function pickDefaultForMode(file: StrategyFile, mode: UseCaseId): StrategyDecision {
  const map: Record<UseCaseId, string> = {
    'content-creation': 'problem-solution',
    'learn-skill': 'tutorial-breakdown',
    'channel-strategy': 'tutorial-breakdown',
    'idea-evaluation': 'myth-busting',
    custom: 'problem-solution',
  };
  const strategy = file.strategies.find((s) => s.id === map[mode]) || file.strategies[0];
  return {
    strategy,
    confidence: 0.5,
    reasoning: `Default strategy for mode "${mode}".`,
    alternatives: [],
  };
}

// ============================================================
// Human-readable reasoning (goes into the prompt)
// ============================================================
function buildReasoning(strategy: Strategy, answers: WizardAnswers): string {
  const lang = answers.outputLanguage;
  const parts: string[] = [];
  if (answers.goal && strategy.best_for_goals.includes(answers.goal)) {
    parts.push(
      lang === 'en'
        ? `aligned with goal "${translateToEn(answers.goal)}"`
        : `aligned with goal "${answers.goal}"`,
    );
  }
  if (answers.tone && strategy.best_for_tones.includes(answers.tone)) {
    parts.push(
      lang === 'en'
        ? `matches tone "${translateToEn(answers.tone)}"`
        : `matches tone "${answers.tone}"`,
    );
  }
  if (answers.contentType && strategy.best_for_content_types.includes(answers.contentType)) {
    parts.push(`suited for "${answers.contentType}"`);
  }
  return parts.length > 0
    ? `Selected because it's ${parts.join(', ')}.`
    : `Selected as best general fit for this context.`;
}

function translateToEn(v: string): string {
  // Lazy import to avoid circular dependency
  const map: Record<string, string> = {
    'تشجيع الجمهور على البدء': 'encourage starting',
    'توعية وزيادة معرفة': 'awareness',
    'الترويج لمنتج أو خدمة': 'product promotion',
    'الترويج لكورس': 'course promotion',
    'بناء براند شخصي': 'personal brand',
    'زيادة المشاهدات والمتابعين': 'views & followers',
    'توليد تفاعل': 'engagement',
    'كوميدي': 'comedic',
    'جدي احترافي': 'serious',
    'تحفيزي': 'inspirational',
    'تعليمي مبسط': 'educational',
    'صادم ومثير للجدل': 'provocative',
    'هادئ وودود': 'calm',
  };
  return map[v] ?? v;
}