import { siteConfig } from '@/config/site.config';
import { useLanguage } from '@/components/layout/LanguageProvider';
import type { DnaSection } from '@/types/prompt.types';

interface Props {
  sections: DnaSection[];
  strategy?: string;
  strategyConfidence?: number;
}

export function PromptDNAVisualizer({ sections, strategy, strategyConfidence }: Props) {
  const { t } = useLanguage();

  if (sections.length === 0) return null;

  return (
    <div className="rounded-xl border border-border bg-surface p-4">
      <div className="mb-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-xl">🧬</span>
          <h3 className="text-sm font-bold text-text-primary">{t('dna.title')}</h3>
        </div>
        {strategy && (
          <div className="flex items-center gap-2 text-xs">
            <span className="text-text-muted">{t('dna.strategy')}:</span>
            <span className="rounded-md bg-primary/10 px-2 py-0.5 font-bold text-primary">
              {strategy}
            </span>
            {strategyConfidence !== undefined && (
              <span className="text-text-muted">
                ({Math.round(strategyConfidence * 100)}%)
              </span>
            )}
          </div>
        )}
      </div>

      <div className="mb-4 flex h-3 w-full overflow-hidden rounded-full">
        {sections.map((s) => (
          <div
            key={s.category}
            style={{ width: `${s.weight}%`, backgroundColor: s.color }}
            title={`${s.name}: ${s.weight}%`}
          />
        ))}
      </div>

      <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
        {sections.map((s) => (
          <div key={s.category} className="flex items-center gap-2 text-xs">
            <div className="h-3 w-3 rounded-sm" style={{ backgroundColor: s.color }} />
            <span className="text-text-secondary">
              {s.name} <span className="text-text-muted">({s.weight}%)</span>
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}