import type { ComposedPrompt } from '@/types/prompt.types';

export function downloadTxt(prompt: ComposedPrompt, filename = 'prompt') {
  const text = prompt.prompts.join('\n\n' + '='.repeat(60) + '\n\n');
  triggerDownload(text, `${filename}.txt`, 'text/plain');
}

export function downloadMd(prompt: ComposedPrompt, filename = 'prompt') {
  const text = prompt.prompts
    .map((p, i) => (prompt.prompts.length > 1 ? `# Prompt ${i + 1}\n\n${p}` : p))
    .join('\n\n---\n\n');
  triggerDownload(text, `${filename}.md`, 'text/markdown');
}

export function downloadJson(prompt: ComposedPrompt, filename = 'prompt') {
  triggerDownload(JSON.stringify(prompt, null, 2), `${filename}.json`, 'application/json');
}

function triggerDownload(text: string, filename: string, mime: string) {
  const blob = new Blob([text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}