// ============================================================
// CompatibilityChecker — checks that selected terms work together
// ============================================================

import type { EnrichedTerm } from '@/types/knowledge.types';

export interface CompatibilityPair {
  a: number;
  b: number;
  score: number; // -1 to +1
  reason: string;
}

export interface CompatibilityFile {
  version: string;
  default_compatibility: number;
  pairs: CompatibilityPair[];
}

export interface CompatibilityResult {
  overallScore: number; // -1 to +1, average
  conflicts: CompatibilityPair[];
  synergies: CompatibilityPair[];
  suggestions: string[];
}

// ============================================================
// Main check
// ============================================================
export function checkCompatibility(
  file: CompatibilityFile,
  terms: EnrichedTerm[],
): CompatibilityResult {
  if (terms.length < 2) {
    return { overallScore: 0, conflicts: [], synergies: [], suggestions: [] };
  }

  const idSet = new Set(terms.map((t) => t.id));
  const lookup = new Map<string, CompatibilityPair>();
  for (const p of file.pairs) {
    lookup.set(pairKey(p.a, p.b), p);
  }

  const pairs: CompatibilityPair[] = [];
  for (let i = 0; i < terms.length; i++) {
    for (let j = i + 1; j < terms.length; j++) {
      const a = terms[i].id;
      const b = terms[j].id;
      const known = lookup.get(pairKey(a, b));
      if (known) {
        pairs.push(known);
      } else {
        pairs.push({
          a,
          b,
          score: file.default_compatibility,
          reason: 'Neutral (no specific relationship)',
        });
      }
    }
  }

  const conflicts = pairs.filter((p) => p.score < -0.15);
  const synergies = pairs.filter((p) => p.score > 0.6);
  const overallScore = pairs.reduce((s, p) => s + p.score, 0) / pairs.length;

  const suggestions: string[] = [];
  if (conflicts.length > 0) {
    for (const c of conflicts.slice(0, 3)) {
      suggestions.push(
        `Consider dropping one of (#${c.a} / #${c.b}): ${c.reason}`,
      );
    }
  }
  if (synergies.length > 0) {
    suggestions.push(
      `Strong synergy detected (${synergies.length} pairs). Good combination!`,
    );
  }

  return { overallScore, conflicts, synergies, suggestions };
}

function pairKey(a: number, b: number): string {
  return a < b ? `${a}-${b}` : `${b}-${a}`;
}

// ============================================================
// Filter: remove conflicting terms
// ============================================================
export function filterConflicts(
  file: CompatibilityFile,
  terms: EnrichedTerm[],
): EnrichedTerm[] {
  if (terms.length < 2) return terms;

  const lookup = new Map<string, number>();
  for (const p of file.pairs) {
    lookup.set(pairKey(p.a, p.b), p.score);
  }

  // Greedy: keep highest-weighted term, drop conflicting ones
  const sorted = [...terms].sort((a, b) => {
    const wa = Object.values(a.injection_weight).reduce((s, w) => s + w, 0);
    const wb = Object.values(b.injection_weight).reduce((s, w) => s + w, 0);
    return wb - wa;
  });

  const kept: EnrichedTerm[] = [];
  for (const t of sorted) {
    let hasConflict = false;
    for (const k of kept) {
      const score = lookup.get(pairKey(t.id, k.id)) ?? file.default_compatibility;
      if (score < -0.15) {
        hasConflict = true;
        break;
      }
    }
    if (!hasConflict) kept.push(t);
  }
  return kept;
}