// ============================================================
// ModelOptimizer — adapts the rendered prompt for a specific AI model
// Strategy: prepend model-specific wrapper + optional style tweaks
// ============================================================

import type { AiModel } from '@/types/knowledge.types';

const MODEL_HEADERS: Record<AiModel, string> = {
  chatgpt:
    '> You are running inside ChatGPT. Follow the structured instructions below exactly. Think step by step in private before responding. Do not skip the DISCOVERY phase.',

  claude:
    '> You are running inside Claude. This prompt uses Markdown sections. Respect all XML-inline constraints and follow the QUALITY CHECKLIST at the end before responding.',

  gemini:
    '> You are running inside Gemini. Sections are clearly labeled with # headers. Preserve the order of execution. Do not omit the QUESTION PROTOCOL.',

  deepseek:
    '> You are running inside DeepSeek. The instructions below are directive. Follow them in sequence, without skipping. Prioritize the DISCOVERY phase over any urge to generate content immediately.',

  agnostic:
    '> This prompt is model-agnostic. Follow the structure exactly. Do not skip any phase.',
};

export function optimizeForModel(prompt: string, model: AiModel): string {
  const header = MODEL_HEADERS[model] || MODEL_HEADERS.agnostic;
  return `${header}\n\n${prompt}`;
}