// ============================================================
// Enhanced TermSelector — 6-criteria scoring with two-pass
// compatibility adjustment.
//
// Formula: S = 0.30R + 0.20P + 0.15T + 0.15D + 0.10Q + 0.10C
//   R = Relevance     (injection_weight + tag bonuses)
//   P = Platform Fit  (platform tag overlap)
//   T = Tone Fit      (tone tag overlap)
//   D = Difficulty Fit (complexity match with audience level)
//   Q = Quality Evidence (derived from citation richness)
//   C = Compatibility  (average pairwise compatibility — Pass 2 only)
// ============================================================

import type {
  EnrichedTerm,
  LengthMode,
  TermMetadata,
  TermMetadataFile,
} from '@/types/knowledge.types';
import type { TermSelectionResult } from '@/types/prompt.types';
import type { WizardAnswers } from '@/types/wizard.types';
import type { DerivedContext } from '@/types/context.types';
import type { CompatibilityFile } from './CompatibilityChecker';

const LENGTH_TARGETS: Record<LengthMode, number> = {
  compact: 6,
  standard: 15,
  comprehensive: 25,
};

const PLATFORM_TAGS: Record<string, string[]> = {
  tiktok: ['short-form', 'hook', 'retention', 'vertical', 'scroll-stopper'],
  reels: ['short-form', 'hook', 'retention', 'vertical'],
  'youtube-shorts': ['short-form', 'hook', 'retention'],
  'youtube-long': ['storytelling', 'depth', 'long-form', 'watch-time'],
  facebook: ['relatability', 'shareability', 'storytelling'],
  linkedin: ['authority', 'professionalism', 'credibility', 'business'],
  x: ['hook', 'punchy', 'opinion', 'provocative'],
  blog: ['depth', 'structure', 'seo', 'long-form'],
  podcast: ['storytelling', 'conversation', 'depth'],
  all: [],
};

const TONE_TAGS: Record<string, string[]> = {
  comedic: ['surprise', 'relatability', 'shock', 'energy', 'humor'],
  serious: ['credibility', 'authority', 'depth', 'professionalism'],
  inspirational: ['emotional-arc', 'transformation', 'hope', 'story'],
  educational: ['framework', 'structure', 'clarity', 'step-by-step'],
  provocative: ['shock', 'contrarian', 'curiosity', 'emotion'],
  calm: ['relatability', 'empathy', 'storytelling'],
};

const CITATION_KEYWORDS = [
  'HubSpot', 'Cialdini', 'Harvard', 'Stanford', 'Berkeley', 'Sprout',
  'BuzzSumo', 'Wistia', 'Neil Patel', 'Copyblogger', 'SEMrush',
  'Shopify', 'ConvertKit', 'Unbounce', 'Pixar', 'Robert McKee',
  'University of Pennsylvania', 'Social Media Examiner', 'Vidyard',
];

// ============================================================
// Public API
// ============================================================
export function selectTerms(
  metadata: TermMetadataFile,
  answers: WizardAnswers,
  compatibility: CompatibilityFile,
  derived: DerivedContext,
): TermSelectionResult {
  const allTerms = metadata.terms as TermMetadata[];
  const mode = answers.mode;

  // ---- CUSTOM: manual selection wins ----
  if (mode === 'custom' && answers.customTermIds?.length) {
    const selected = allTerms.filter((t) =>
      answers.customTermIds!.includes(t.id),
    ) as EnrichedTerm[];
    return wrapResult(selected, 'Custom manual selection');
  }

  // ---- LEARN-SKILL: focus + related (coach = focus only) ----
  if (mode === 'learn-skill' && answers.skillTermId) {
    const target = allTerms.find((t) => t.id === answers.skillTermId);
    if (target) {
      const isCoach = answers.learningStyle === 'coach';
      const relatedIds = isCoach
        ? new Set<number>()
        : new Set<number>(target.related_terms.slice(0, 3));
      const related = allTerms.filter((t) => relatedIds.has(t.id));
      const selected = [target, ...related] as EnrichedTerm[];
      const reasonSuffix = isCoach
        ? '(coach: focus term only)'
        : `(+${related.length} related)`;
      return wrapResult(selected, `Learn-skill focus: ${target.term_en} ${reasonSuffix}`);
    }
  }

  // ---- Standard selection: two-pass with compatibility ----
  const limit = LENGTH_TARGETS[answers.lengthMode || 'standard'];

  // PASS 1: base score (R + P + T + D + Q)
  const pass1 = allTerms.map((t) => ({
    term: t,
    base: computeBaseScore(t, answers, mode, derived),
  }));
  pass1.sort((a, b) => b.base - a.base);

  // Take top 30 for compatibility check
  const top30 = pass1.slice(0, 30);

  // PASS 2: adjust with compatibility
  const compatLookup = buildCompatLookup(compatibility);
  const pass2 = top30.map(({ term, base }) => {
    const compatScore = avgCompatibilityWithSet(term.id, top30.map((x) => x.term.id), compatLookup);
    return {
      term,
      base,
      withCompat: base + 0.10 * normalizeCompat(compatScore) * 100,
    };
  });
  pass2.sort((a, b) => b.withCompat - a.withCompat);

  // Diversity cap: max 1/3 from any single category
  const categoryCap = Math.max(3, Math.floor(limit / 3));
  const categoryCount: Record<string, number> = {};
  const selected: TermMetadata[] = [];
  for (const { term } of pass2) {
    categoryCount[term.category] = (categoryCount[term.category] || 0) + 1;
    if (categoryCount[term.category] <= categoryCap) {
      selected.push(term);
    }
    if (selected.length >= limit) break;
  }

  return wrapResult(
    selected as EnrichedTerm[],
    `6-criteria selection (top ${selected.length} of ${pass2.length})`,
  );
}

// ============================================================
// Base score: 0.30R + 0.20P + 0.15T + 0.15D + 0.10Q  (range 0-90)
// ============================================================
function computeBaseScore(
  term: TermMetadata,
  answers: WizardAnswers,
  mode: WizardAnswers['mode'],
  derived: DerivedContext,
): number {
  const R = computeRelevance(term, answers, mode); // 0-100
  const P = computePlatformFit(term, derived); // 0-100
  const T = computeToneFit(term, derived); // 0-100
  const D = computeDifficultyFit(term, derived); // 0-100
  const Q = computeQualityEvidence(term); // 0-100

  return 0.30 * R + 0.20 * P + 0.15 * T + 0.15 * D + 0.10 * Q;
}

// R: Relevance (0-100) — injection weight × 10 + tag bonuses
function computeRelevance(
  term: TermMetadata,
  answers: WizardAnswers,
  mode: WizardAnswers['mode'],
): number {
  const weight = (term.injection_weight[mode as keyof typeof term.injection_weight] || 0) * 10;

  // Tag bonuses from pain point, goal, etc.
  let bonus = 0;
  const painLower = (answers.painPoint || '').toLowerCase();
  if (painLower.includes('صعب') && term.tags.includes('framework')) bonus += 5;
  if (painLower.includes('يبدأ') && term.tags.includes('hook')) bonus += 5;
  if (painLower.includes('معلومات خاطئة') && term.tags.includes('shock')) bonus += 8;

  return Math.min(100, weight + bonus);
}

// P: Platform Fit (0-100) — overlap between term tags and platform tags
function computePlatformFit(term: TermMetadata, derived: DerivedContext): number {
  const platformTags = PLATFORM_TAGS[derived.platformKey] || [];
  if (platformTags.length === 0) return 50; // neutral
  const hits = term.tags.filter((t) => platformTags.includes(t)).length;
  return Math.min(100, hits * 25);
}

// T: Tone Fit (0-100) — overlap between term tags and tone tags
function computeToneFit(term: TermMetadata, derived: DerivedContext): number {
  const toneTags = TONE_TAGS[derived.toneKey] || [];
  if (toneTags.length === 0) return 50;
  const hits = term.tags.filter((t) => toneTags.includes(t)).length;
  return Math.min(100, hits * 30);
}

// D: Difficulty Fit (0-100) — match between term complexity and audience level
function computeDifficultyFit(term: TermMetadata, derived: DerivedContext): number {
  const map: Record<string, Record<string, number>> = {
    beginner: { beginner: 100, intermediate: 60, advanced: 20 },
    intermediate: { beginner: 70, intermediate: 100, advanced: 70 },
    advanced: { beginner: 40, intermediate: 70, advanced: 100 },
  };
  return map[derived.audienceLevel]?.[term.complexity] ?? 50;
}

// Q: Quality Evidence (0-100) — derived from citation richness in summary
function computeQualityEvidence(term: TermMetadata): number {
  let score = 50; // baseline
  for (const kw of CITATION_KEYWORDS) {
    if (term.prompt_summary.includes(kw)) score += 8;
  }
  if (term.prompt_summary.length > 200) score += 5;
  if (term.related_terms.length >= 4) score += 5;
  if (term.prompt_example.includes('🇪🇬') || term.prompt_example.length > 100) score += 5;
  return Math.min(100, score);
}

// ============================================================
// Compatibility helpers (Pass 2)
// ============================================================
function buildCompatLookup(file: CompatibilityFile): Map<string, number> {
  const map = new Map<string, number>();
  for (const p of file.pairs) {
    const key = p.a < p.b ? `${p.a}-${p.b}` : `${p.b}-${p.a}`;
    map.set(key, p.score);
  }
  return map;
}

function avgCompatibilityWithSet(
  termId: number,
  otherIds: number[],
  lookup: Map<string, number>,
): number {
  let sum = 0;
  let count = 0;
  for (const other of otherIds) {
    if (other === termId) continue;
    const key = termId < other ? `${termId}-${other}` : `${other}-${termId}`;
    sum += lookup.get(key) ?? 0.2; // default neutral
    count++;
  }
  return count > 0 ? sum / count : 0.2;
}

// Convert [-1, +1] to [0, +1]
function normalizeCompat(raw: number): number {
  return (raw + 1) / 2;
}

// ============================================================
// Result wrapper
// ============================================================
function wrapResult(selected: EnrichedTerm[], reason: string): TermSelectionResult {
  return {
    selected,
    reason,
    totalWeight: selected.reduce(
      (sum, t) => sum + Object.values(t.injection_weight).reduce((s, w) => s + w, 0),
      0,
    ),
    categoryBreakdown: selected.reduce<Record<string, number>>((acc, t) => {
      acc[t.category] = (acc[t.category] || 0) + 1;
      return acc;
    }, {}),
  };
}