import type { EnrichedTerm } from '@/types/knowledge.types';
import type { ComposedProtocol } from './ProtocolComposer';
import { TEMPLATE_MAP } from './templates';
import type { WizardAnswers } from '@/types/wizard.types';
import type { ProtocolId } from '@/types/protocol.types';
import type { DerivedContext } from '@/types/context.types';
import type { StrategyDecision } from './StrategyPlanner';
import { getEnglishExampleSync } from '@/lib/utils/dataLoader';
import { toEnglish } from '@/lib/i18n/valueTranslations';

export interface RenderContext {
  answers: WizardAnswers;
  composed: ComposedProtocol;
  terms: EnrichedTerm[];
  strategy: StrategyDecision;
  derived: DerivedContext;
  usedProfile: boolean;
  profileName?: string;
  protocolId: ProtocolId;
}

// ============================================================
// Knowledge block — language-aware examples
// ============================================================
function formatKnowledgeBlock(
  terms: EnrichedTerm[],
  lang: 'ar' | 'en' | 'bilingual',
): string {
  if (terms.length === 0) return '_No terms injected._';

  const byCategory: Record<string, EnrichedTerm[]> = {};
  for (const t of terms) {
    (byCategory[t.category] ||= []).push(t);
  }

  const blocks: string[] = [];
  for (const [category, catTerms] of Object.entries(byCategory)) {
    blocks.push(`## ${humanizeCategory(category)} (${catTerms.length} terms)`);
    for (const t of catTerms) {
      const example =
        lang === 'en'
          ? getEnglishExampleSync(t.id) || t.prompt_example
          : t.prompt_example;

      blocks.push(
        `### ${t.term_en} / ${t.term_ar}\n` +
          `- Summary: ${t.prompt_summary}\n` +
          `- Example: ${example}`,
      );
    }
  }
  return blocks.join('\n\n');
}

function humanizeCategory(cat: string): string {
  const map: Record<string, string> = {
    'writing-hacks': 'Writing Hacks',
    storytelling: 'Storytelling',
    'camera-presence': 'Camera Presence',
    hooks: 'Hook & Micro Hooks',
    cta: 'Call to Action',
    editing: 'Editing & Montage',
  };
  return map[cat] || cat;
}

// ============================================================
// User context — language-aware values + explicit Output Language
// ============================================================
function formatUserContext(
  answers: WizardAnswers,
  strategy: StrategyDecision,
  derived: DerivedContext,
  usedProfile: boolean,
  profileName: string | undefined,
  lang: 'ar' | 'en' | 'bilingual',
): string {
  const lines: string[] = [];
  const tr = lang === 'en' ? toEnglish : (v?: string) => v;
  const resolve = (value?: string | null, custom?: string | null) =>
    value === '__other__' ? custom : value;
  const push = (label: string, value?: string | number | undefined | null) => {
    if (value !== undefined && value !== null && value !== '') {
      lines.push(`- **${label}:** ${value}`);
    }
  };

  // ✨ حاسم — AI يحتاج معرفة اللغة المطلوبة
  push(
    'Output Language',
    lang === 'ar' ? 'Arabic' : lang === 'en' ? 'English' : 'Bilingual (Arabic + English)',
  );
  push(
    'Output Language Instruction',
    lang === 'ar'
      ? 'Respond in professional Egyptian Arabic dialect.'
      : lang === 'en'
        ? 'Respond in clear, professional English. Translate any Arabic instructions/examples in this prompt before responding. Provide examples in English only.'
        : 'Provide parallel Arabic + English versions (Arabic first, English second).',
  );

  push('Mode', answers.mode);
  push('Niche / Field', tr(resolve(
    answers.niche || answers.channelNiche || answers.ideaNiche,
    answers.nicheCustom || answers.channelNicheCustom || answers.ideaNicheCustom,
  ) as string | undefined));
  push('Audience', tr(resolve(answers.audience, answers.audienceCustom) as string | undefined));
  push('Goal', tr(resolve(answers.goal, answers.goalCustom) as string | undefined));
  push('Pain Point', tr(resolve(answers.painPoint, answers.painPointCustom) as string | undefined));
  push('Platform', tr(resolve(
    answers.platform || answers.channelPlatform,
    answers.platformCustom || answers.channelPlatformCustom,
  ) as string | undefined));
  push('Tone', tr(resolve(answers.tone, answers.toneCustom) as string | undefined));
  push('Content Type', tr(answers.contentType));
  push('Topic', answers.topic);
  push('Desired CTA', tr(resolve(answers.ctaType, answers.ctaTypeCustom) as string | undefined));
  push('Preferred Hook Style', tr(answers.hookStyle));
  push('Target Duration', answers.duration);
  push('Target Word Count', answers.wordCount);

  // Strategy info — always English (already in English)
  push('Selected Strategy', `${strategy.strategy.name.en} — ${strategy.strategy.narrative_flow.join(' → ')}`);
  push('Strategy Rationale', strategy.reasoning);
  push('Framework Anchors', strategy.strategy.framework_anchors.join(', '));
  push('Audience Level', derived.audienceLevel);
  push('Normalized Niche', derived.nicheNormalized);
  if (usedProfile) push('Profile', profileName || 'Enabled');

  push('Skill Term ID', answers.skillTermId);
  push('Learning Style', tr(answers.learningStyle));
  push('Depth Level', tr(answers.depthLevel));
  push('Channel Goal', tr(answers.channelGoal));
  push('Channel Status', tr(answers.channelStatus));
  push('Presentation Style', tr(answers.presentationStyle));
  push('Idea', answers.ideaText);
  push('Idea Content Type', tr(resolve(answers.ideaContentType, answers.ideaContentTypeCustom) as string | undefined));
  push('Evaluation Strictness', tr(answers.evaluationStrictness));

  if (answers.customTermIds?.length) {
    push('Custom Terms Count', answers.customTermIds.length);
  }
  push('Additional Notes', answers.additionalNotes);

  return lines.length > 0 ? lines.join('\n') : '_No context provided._';
}

// ============================================================
// Main renderer
// ============================================================
function substitute(template: string, vars: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key: string) => vars[key] ?? `_missing:${key}_`);
}

export function renderTemplate(ctx: RenderContext): string {
  const { answers, composed, terms, strategy, derived, usedProfile, profileName, protocolId } = ctx;
  const template = TEMPLATE_MAP[protocolId] || TEMPLATE_MAP['content-creation'];
  const lang = answers.outputLanguage;

  const vars: Record<string, string> = {
    role: composed.protocol.role_definition,
    common_rules: composed.commonRulesText,
    protocol_rules: composed.protocolRulesText,
    output_language: composed.outputLanguageInstruction,
    knowledge_block: formatKnowledgeBlock(terms, lang),
    user_context: formatUserContext(answers, strategy, derived, usedProfile, profileName, lang),
    question_protocol: composed.questionProtocolText,
    output_structure: composed.outputStructureText,
    quality_checklist: composed.qualityChecklistText,
    closing_questions: composed.closingQuestionsText,
  };

  return substitute(template, vars).trim();
}