// ============================================================
// ProtocolComposer — assembles protocol + common rules
// Language-aware: when lang === 'en', uses English overrides
// ============================================================

import type {
  InteractionProtocol,
  InteractionProtocolsFile,
  ProtocolId,
} from '@/types/protocol.types';
import {
  COMMON_RULES_EN,
  PROTOCOL_EN_OVERRIDES,
  type ProtocolEnOverride,
} from './protocol-translations-en';

export interface ComposedProtocol {
  protocol: InteractionProtocol;
  commonRulesText: string;
  protocolRulesText: string;
  outputLanguageInstruction: string;
  questionProtocolText: string;
  outputStructureText: string;
  qualityChecklistText: string;
  closingQuestionsText: string;
}

export function composeProtocol(
  file: InteractionProtocolsFile,
  protocolId: ProtocolId,
  options?: { outputLanguage?: 'ar' | 'en' | 'bilingual' },
): ComposedProtocol {
  const protocol = file.protocols[protocolId];
  if (!protocol) {
    throw new Error(`Unknown protocol: ${protocolId}`);
  }

  const lang = options?.outputLanguage || 'ar';
  const isEn = lang === 'en';
  const enOverride = isEn ? PROTOCOL_EN_OVERRIDES[protocolId] : undefined;

  // ---- COMMON RULES ----
  const cr = file.common_rules;
  const commonRulesText = isEn
    ? [
        `- OUTPUT LANGUAGE: ${COMMON_RULES_EN.outputLanguageDefault}`,
        `- OVERRIDE: ${COMMON_RULES_EN.outputLanguageOverride}`,
        `- BILINGUAL EXAMPLES: ${COMMON_RULES_EN.bilingualExamples}`,
        `- FRAMEWORK REFERENCES: ${COMMON_RULES_EN.frameworkReferences}`,
        `- EMOJIS: ${COMMON_RULES_EN.emojis}`,
        `- CLOSING: ${COMMON_RULES_EN.closing}`,
        `- ANTI-GENERIC: ${COMMON_RULES_EN.antiGeneric}`,
        `- NO FLATTERY: ${COMMON_RULES_EN.noFlattery}`,
        `- FORMATTING: ${COMMON_RULES_EN.formatting}`,
      ].join('\n')
    : [
        `- OUTPUT LANGUAGE: ${cr.output_language_instruction.default}`,
        `- OVERRIDE: ${cr.output_language_instruction.user_override}`,
        `- BILINGUAL EXAMPLES: ${cr.bilingual_examples_rule}`,
        `- FRAMEWORK REFERENCES: ${cr.framework_reference_rule}`,
        `- EMOJIS: ${cr.emoji_strategy}`,
        `- CLOSING: ${cr.closing_rule}`,
        `- ANTI-GENERIC: ${cr.anti_generic_rule}`,
        `- NO FLATTERY (critique modes): ${cr.no_flattery_rule}`,
        `- FORMATTING: ${cr.formatting_rule}`,
      ].join('\n');

  // ---- BEHAVIOR RULES (with Arabic-phrase fixes when EN) ----
  let behaviorRules = protocol.behavior_rules.slice();
  if (isEn && enOverride?.behaviorRuleFixes) {
    behaviorRules = behaviorRules.map((rule) => {
      let fixed = rule;
      for (const fix of enOverride.behaviorRuleFixes!) {
        fixed = fixed.split(fix.find).join(fix.replace);
      }
      return fixed;
    });
  }
  const protocolRulesText = behaviorRules.map((r, i) => `${i + 1}. ${r}`).join('\n');

  // ---- OUTPUT LANGUAGE (dynamic) ----
  let outputLanguageInstruction = '';
  if (lang === 'ar') {
    outputLanguageInstruction =
      'Respond to the user in PROFESSIONAL EGYPTIAN ARABIC dialect. Not formal MSA. Not heavy slang. Signature voice: «بص، هقولك رأيي من غير مجاملة» / «خلينا نعمل» / «خليني أوضحلك».';
  } else if (lang === 'en') {
    outputLanguageInstruction =
      'Respond to the user in clear, professional English. Do not use Arabic unless quoting an example.';
  } else {
    outputLanguageInstruction =
      'Respond bilingually: provide the full response in ENGLISH first, then an ARABIC version below. Always label each version.';
  }

  // ---- QUESTION PROTOCOL ----
  const qp = protocol.question_protocol;
  const qpEn = enOverride?.questionProtocol;
  const questionLines: string[] = [
    isEn && qpEn ? qpEn.firstMessagePattern : qp.first_message_pattern,
  ];

  if (qp.questions) {
    for (const q of qp.questions) {
      const examples = q.options_en || (q as { examples_en?: string[] }).examples_en || [];
      const questionText =
        isEn && qpEn?.questions
          ? qpEn.questions.find((x) => x.key === q.key)?.question ?? q.ar
          : q.ar;
      questionLines.push(
        `  Q: ${questionText}\n    (Examples only — the user may answer in their own words): ${examples.join(' / ')}`,
      );
    }
  }

  if (qp.diagnostic_questions) {
    for (const q of qp.diagnostic_questions) {
      const questionText =
        isEn && qpEn?.diagnosticQuestions
          ? qpEn.diagnosticQuestions.find((x) => x.key === q.key)?.question ?? q.ar
          : q.ar;
      questionLines.push(`  Q: ${questionText}`);
    }
  }

  if (qp.clarification_prompt) {
    const clar =
      isEn && qpEn?.clarificationPrompt ? qpEn.clarificationPrompt : qp.clarification_prompt;
    questionLines.push(`  Clarification: ${clar}`);
  }

  const questionProtocolText = questionLines.join('\n');

  // ---- OUTPUT STRUCTURE (already English) ----
  const outputStructureText = protocol.output_structure.map((s) => `- ${s}`).join('\n');

  // ---- QUALITY CHECKLIST (already English) ----
  const qualityChecklistText = protocol.quality_checklist
    .map((q) => `- [ ] ${q}`)
    .join('\n');

  // ---- CLOSING QUESTIONS ----
  const closingList =
    isEn && enOverride?.closingQuestions
      ? enOverride.closingQuestions
      : protocol.closing_questions;
  const closingQuestionsText = closingList.map((q) => `- ${q}`).join('\n');

  return {
    protocol,
    commonRulesText,
    protocolRulesText,
    outputLanguageInstruction,
    questionProtocolText,
    outputStructureText,
    qualityChecklistText,
    closingQuestionsText,
  };
}